from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
for directory,prefix in [('lean',''),('arabic','../lean/')]:
 html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PMP · Lean operating guide</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f3f0;color:#202020;font:16px/1.7 Arial,sans-serif}header{background:#7d2b42;color:white;padding:32px max(20px,calc((100% - 1120px)/2))}header small{color:#ffcc00;font-weight:bold}h1{line-height:1.4;margin:12px 0}main{max-width:1160px;margin:auto;padding:24px 20px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}article{background:white;padding:24px;border:1px solid #ddd;border-radius:10px}h2{color:#7d2b42}a,button{display:inline-block;padding:11px 16px;margin:5px 3px;background:#7d2b42;color:white;border:0;border-radius:5px;text-decoration:none;font:inherit;cursor:pointer}.view{background:#ffcc00;color:#202020}.preview{margin-top:26px}iframe{width:100%;height:78vh;border:1px solid #d5d5d5;background:white}small{color:#555}.toolbar{margin:12px 0}a:focus-visible,button:focus-visible{outline:3px solid #202020;outline-offset:3px}@media(max-width:700px){.grid{grid-template-columns:1fr}article{padding:18px}}</style></head><body><header><small>PMP / REVISED LEAN EDITION</small><h1>Clear steps. Clear ownership.<br><span lang="ar" dir="rtl">مين يعمل إيه؟ وإمتى الشغل يبقى جاهز؟</span></h1><p>5-page operating guide + 10-slide briefing, in both languages.</p><p lang="ar" dir="rtl">دليل عملي ٥ صفحات وعرض ١٠ شرائح. العربي مكتوب بالمصري المهني، والنسختين فيهم نفس قواعد التشغيل.</p></header><main><div class="grid">'''
 for lang,title,desc in [('AR','العربي بالمصري','دليل للمالك ومدير التسويق: الخطوات، المسؤوليات، الموافقات، المتابعة والتقييم الشهري.'),('EN','English','One concise guide for the owner and Marketing Manager: workflow, ownership, approvals and monthly reviews.')]:
  direction=' lang="ar" dir="rtl"' if lang=='AR' else ''
  html+=f'<article{direction}><h2>{title}</h2><p>{desc}</p>'
  for label,stem,ext in [('دليل التشغيل' if lang=='AR' else 'Operating guide',f'PMP-Lean-Operating-Guide-{lang}','docx'),('عرض التشغيل' if lang=='AR' else 'Briefing deck',f'PMP-Lean-Playbook-{lang}','pptx')]:
   html+=f'<p><strong>{label}</strong><br><a class="view" href="{prefix}{stem}.pdf">'+('عرض PDF' if lang=='AR' else 'View PDF')+f'</a><a href="{prefix}{stem}.{ext}" download>'+('تحميل ' if lang=='AR' else 'Download ')+ext.upper()+'</a></p>'
  html+='</article>'
 html+='</div><section class="preview"><h2>Read here / اقرأ هنا</h2><div class="toolbar">'
 for lang,label in [('AR','الدليل العربي'),('EN','English guide')]:html+=f'<button type="button" data-src="{prefix}PMP-Lean-Operating-Guide-{lang}.pdf">{label}</button>'
 html+=f'</div><iframe id="reader" title="PMP operating guide PDF" src="{prefix}PMP-Lean-Operating-Guide-AR.pdf"></iframe><p><small>If your browser cannot show PDFs here, use the View PDF links above. لو المعاينة مش شغالة على جهازك، افتح رابط عرض PDF فوق.</small></p></section><p><small>30 October 2026 · Revised concise edition. Previous long files remain available in the repository archive. Private client/staff records are excluded.</small></p></main><script>document.querySelectorAll("button[data-src]").forEach(b=>b.addEventListener("click",()=>document.getElementById("reader").src=b.dataset.src));</script></body></html>'
 (ROOT/directory/'index.html').write_text(html)
